1	/** Private installed-test association only. Never a ConformanceRunResult or admission artifact. */
2	import { createHash, randomUUID } from "node:crypto";
3	import { existsSync, renameSync, rmSync, writeFileSync } from "node:fs";
4	import { isDeepStrictEqual } from "node:util";
5	import {
6	  canonicalJson,
7	  selectApplicableScenariosForProfile,
8	  type ConformanceRunResult,
9	  type ExactHttpConfiguration,
10	} from "@bdp/conformance";
11	import {
12	  assertReadUpdateArtifactSet,
13	  assertSameServedProfileConfiguration,
14	  bindServedProfileConfiguration,
15	  type ReadUpdateArtifactSet,
16	} from "@bdp/conformance/testing";
17	import { installedContractsDigest } from "./installed-contract-identity.js";
18	
19	type Bundle = ReadUpdateArtifactSet["shards"][number]["bundle"];
20	export function artifactRoutes(bundle: Bundle, scope: string) {
21	  const known: Record<string, string> = {
22	    ...Object.fromEntries(
23	      Object.entries(bundle.fixture.bindings).map(([key, value]) => [
24	        key,
25	        new URL(value, scope).href,
26	      ]),
27	    ),
28	    scope,
29	    "service-desc": `${scope}bdp.json`,
30	    beads: `${scope}beads/`,
31	    links: `${scope}links/`,
32	    types: `${scope}types/`,
33	    operations: `${scope}operations/`,
34	  };
35	  const reads = bundle.manifest.scenarios.flatMap((row) =>
36	    (row.actions ?? row.requests).flatMap((action) => {
37	      if ("family" in action && action.family !== "http") return [];
38	      const base = known[action.target.binding];
39	      if (!base) throw Error("Read target binding is not in the fixed fixture");
40	      const url = new URL(action.target.path ?? "", base);
41	      for (const [key, input] of Object.entries(action.target.query ?? {}))
42	        for (const value of Array.isArray(input) ? input : [input]) {
43	          if (typeof value !== "string") throw Error("Read fixture query requires literal strings");
44	          url.searchParams.append(key, value);
45	        }
46	      return [{ method: action.method, url: url.href }];
47	    }),
48	  );
49	  const clients = bundle.manifest.scenarios.flatMap((row) =>
50	    (row.actions ?? []).flatMap((action) => {
51	      if (action.family !== "client" || action.operation !== "installed.exact-request") return [];
52	      const input = action.input as Record<string, unknown>;
53	      if (input.method !== "GET" || typeof input.targetBinding !== "string") return [];
54	      const url = known[input.targetBinding];
55	      return url === undefined ? [] : [{ method: "GET" as const, url }];
56	    }),
57	  );
58	  const routes = [
59	    ...clients,
60	    ...reads,
61	    ...[
62	      "sequence",
63	      "create-bead",
64	      "update-bead",
65	      "delete-bead",
66	      "create-link",
67	      "update-link",
68	      "delete-link",
69	      "put-alias",
70	      "delete-alias",
71	    ].map((suffix) => ({ method: "POST" as const, url: `${scope}operations/${suffix}` })),
72	  ];
73	  return routes.filter(
74	    (r, n) => routes.findIndex((other) => r.method === other.method && r.url === other.url) === n,
75	  );
76	}
77	export type ArtifactObservation = {
78	  readonly sourceCommit: string;
79	  readonly configuration: ReturnType<typeof bindServedProfileConfiguration>;
80	  readonly baselineReceipt: Record<string, unknown>;
81	  readonly sessions: readonly Record<string, unknown>[];
82	  readonly result: ConformanceRunResult;
83	  readonly exactConfiguration: ExactHttpConfiguration;
84	  readonly plannedManifestDigest: string | undefined;
85	  readonly catalogSources: Readonly<Record<string, string>>;
86	  readonly plannedIds: readonly string[];
87	  readonly requiredIds: readonly string[];
88	  readonly cleanupComplete: boolean;
89	};
90	function equal(actual: unknown, expected: unknown, label: string) {
91	  if (!isDeepStrictEqual(actual, expected)) throw Error(`artifact-set ${label} mismatch`);
92	}
93	function readySummary(receipt: Record<string, unknown>) {
94	  return Object.fromEntries(
95	    [
96	      "scope",
97	      "profile",
98	      "history",
99	      "payloadIdentity",
100	      "artifactIdentity",
101	      "policyIdentity",
102	      "authenticationIdentity",
103	      "configurationIdentity",
104	      "listenUrl",
105	    ]
106	      .filter((key) => receipt[key] !== undefined)
107	      .map((key) => [key, receipt[key]]),
108	  );
109	}
110	function digest(value: unknown) {
111	  return createHash("sha256").update(canonicalJson(value)).digest("hex");
112	}
113	
114	/** Maps actual returned rows. Missing observations stay null; no runner result is invented. */
115	function requiredObservations(
116	  set: ReadUpdateArtifactSet,
117	  results: readonly (ConformanceRunResult | undefined)[],
118	) {
119	  const resultDigests = results.map((result) =>
120	    result === undefined ? undefined : digest(result),
121	  );
122	  const required = set.requirements.map(({ id, owner }) => {
123	    const index = owner === null ? 0 : set.shards.findIndex((s) => s.id === owner);
124	    const result = results[index];
125	    const rowIndex = result?.scenarios.findIndex((r) => r.id === id) ?? -1;
126	    const row = rowIndex < 0 ? undefined : result?.scenarios[rowIndex];
127	    return {
128	      id,
129	      owner,
130	      observation:
131	        row === undefined
132	          ? null
133	          : {
134	              shardId: set.shards[index]!.id,
135	              resultDigest: resultDigests[index],
136	              rowIndex,
137	              state: row.state,
138	              ...(row.category ? { category: row.category } : {}),
139	            },
140	      ...(owner === null
141	        ? { reason: "not-planned" as const }
142	        : row === undefined
143	          ? { reason: "unobserved" as const }
144	          : {}),
145	    };
146	  });
147	  const partitions = {
148	    pass: required.filter((r) => r.observation?.state === "pass").map((r) => r.id),
149	    fail: required.filter((r) => r.observation?.state === "fail").map((r) => r.id),
150	    notRun: required.filter((r) => r.observation?.category === "not-run").map((r) => r.id),
151	    notImplemented: required
152	      .filter((r) => r.observation?.category === "not-implemented")
153	      .map((r) => r.id),
154	    other: required
155	      .filter(
156	        (r) =>
157	          r.observation &&
158	          !["pass", "fail"].includes(r.observation.state) &&
159	          !["not-run", "not-implemented"].includes(r.observation.category ?? ""),
160	      )
161	      .map((r) => r.id),
162	    unobserved: required.filter((r) => r.observation === null).map((r) => r.id),
163	  };
164	  return {
165	    requiredObservations: required,
166	    // Returned owner outcomes, excluding missing-plan/not-run placeholders. State
167	    // partitions expose aborted/skipped outcomes without calling them passes.
168	    observedIds: required
169	      .filter(
170	        (r) =>
171	          r.owner !== null &&
172	          r.observation !== null &&
173	          !["not-run", "not-implemented"].includes(r.observation.category ?? ""),
174	      )
175	      .map((r) => r.id),
176	    observedStatePartitions: partitions,
177	    uncoveredIds: set.coverage.rows.filter((r) => !r.wholeContract).map((r) => r.id),
178	  };
179	}
180	
181	export function associateArtifactObservations(
182	  set: ReadUpdateArtifactSet,
183	  sourceCommit: string,
184	  observations: readonly ArtifactObservation[],
185	) {
186	  assertReadUpdateArtifactSet(set);
187	  if (observations.length !== set.shards.length)
188	    throw Error("artifact-set missing or extra report");
189	  const first = observations[0]!;
190	  const summary = set.shards.map((shard, index) => {
191	    const report = observations[index]!;
192	    const { result, configuration } = report;
193	    if (!report.cleanupComplete) throw Error("artifact-set cleanup incomplete");
194	    equal(report.sourceCommit, sourceCommit, "source");
195	    equal(configuration.sourceCommit, sourceCommit, "configuration source");
196	    assertSameServedProfileConfiguration(first.configuration, configuration);
197	    equal(configuration.fixtureDigest, set.digests.fixtureDigest, "configuration fixture");
198	    equal(configuration.profile, "read-update", "profile");
199	    equal(configuration.history, false, "History");
200	    equal(report.catalogSources, set.digests.catalogDigests, "catalog source map");
201	    equal(report.plannedIds, shard.scenarioIds, "owned plans");
202	    equal(
203	      report.requiredIds,
204	      set.requirements.map((r) => r.id),
205	      "required inventory",
206	    );
207	    equal(report.plannedManifestDigest, shard.bundle.digests.manifestDigest, "planned manifest");
208	    equal(result.artifacts, shard.bundle.digests, "report artifacts");
209	    equal(result.profile, configuration.profile, "report profile");
210	    equal(result.scope, configuration.scope, "report Scope");
211	    equal(result.claimEligible, false, "claim");
212	    equal(result.reportVersion, 4, "report version");
213	    equal(result.seed, shard.bundle.fixture.seed, "seed");
214	    equal(result.scenarioFilter, undefined, "filter");
215	    const selected =
216	      index === 0
217	        ? selectApplicableScenariosForProfile(shard.bundle.catalog, "read-update").map((r) => r.id)
218	        : shard.scenarioIds;
219	    equal(
220	      result.scenarioSelection,
221	      index === 0 ? undefined : shard.scenarioIds,
222	      "requested selection",
223	    );
224	    equal(result.selectedScenarioIds, selected, "selected IDs");
225	    equal(
226	      result.scenarios.map((r) => r.id),
227	      selected,
228	      "result IDs",
229	    );
230	    const owned = new Set(shard.scenarioIds);
231	    for (const row of result.scenarios) {
232	      if (row.cleanupError !== undefined) throw Error(`artifact-set row cleanup failure ${row.id}`);
233	      if (owned.has(row.id)) equal(row.state, "pass", `owned outcome ${row.id}`);
234	      else {
235	        equal(row.state, "harness-error", `unplanned outcome ${row.id}`);
236	        equal(row.category, "not-implemented", `unplanned category ${row.id}`);
237	        equal(row.exchanges, [], `unplanned exchanges ${row.id}`);
238	        equal(row.actions?.length ?? 0, 0, `unplanned actions ${row.id}`);
239	      }
240	    }
241	    const exact = report.exactConfiguration;
242	    equal(exact.scope, configuration.scope, "route Scope");
243	    equal(exact.profile, configuration.profile, "route profile");
244	    equal(exact.routes, artifactRoutes(shard.bundle, configuration.scope), "routes");
245	    equal(exact.defaultCredentialRef, "operator", "default credential handle");
246	    equal(
247	      exact.credentialHandles,
248	      [
249	        { id: "operator", headerNames: ["authorization"] },
250	        { id: "anonymous", headerNames: [] },
251	        { id: "unknown", headerNames: ["authorization"] },
252	      ],
253	      "credential handles",
254	    );
255	    equal(exact.maximumRequestHeaderBytes, 16384, "header bound");
256	    equal(exact.maximumRequestBodyBytes, 131072, "body bound");
257	    const routeDigest = digest({
258	      scope: exact.scope,
259	      profile: exact.profile,
260	      routes: exact.routes,
261	      maximumRequestHeaderBytes: exact.maximumRequestHeaderBytes,
262	      maximumRequestBodyBytes: exact.maximumRequestBodyBytes,
263	    });
264	    equal(
265	      "exactConfigurationDigest" in result.declarations
266	        ? result.declarations.exactConfigurationDigest
267	        : undefined,
268	      routeDigest,
269	      "route digest",
270	    );
271	    equal(
272	      report.sessions.map((s) => s.scenario),
273	      shard.scenarioIds,
274	      "actual sessions",
275	    );
276	    for (const receipt of [report.baselineReceipt, ...report.sessions]) {
277	      equal(
278	        receipt.configurationIdentity,
279	        first.baselineReceipt.configurationIdentity,
280	        "actual runtime configuration",
281	      );
282	      equal(receipt.scope, configuration.scope, "actual Scope");
283	      equal(receipt.profile, configuration.profile, "actual profile");
284	      equal(receipt.history, configuration.history, "actual History");
285	      equal(receipt.payloadIdentity, configuration.installedPayloadDigest, "actual payload");
286	      equal(
287	        installedContractsDigest(receipt.artifactIdentity),
288	        configuration.installedContractsDigest,
289	        "actual contracts",
290	      );
291	      equal(receipt.policyIdentity, configuration.policyDigest, "actual policy");
292	      equal(
293	        receipt.authenticationIdentity,
294	        configuration.authenticationDigest,
295	        "actual authentication",
296	      );
297	    }
298	    return {
299	      id: shard.id,
300	      source: shard.source,
301	      selectionMode: index === 0 ? "unfiltered" : "owned-exact",
302	      requestedIds: result.scenarioSelection ?? null,
303	      selectedIds: result.selectedScenarioIds,
304	      resultIds: result.scenarios.map((r) => r.id),
305	      manifestDigest: shard.bundle.digests.manifestDigest,
306	      routeDigest,
307	      routes: exact.routes,
308	      resultDigest: digest(result),
309	      resultBytes: Buffer.byteLength(canonicalJson(result)),
310	      actualBootstrap: readySummary(report.baselineReceipt),
311	      actualSessions: report.sessions.map((s) => ({ scenario: s.scenario, ...readySummary(s) })),
312	      cleanupComplete: report.cleanupComplete,
313	    };
314	  });
315	  return {
316	    claimEligible: false as const,
317	    sourceCommit,
318	    ...set.digests,
319	    sourceBytes: set.sourceBytes,
320	    configuration: first.configuration,
321	    runtimeConfigurationIdentity: first.baselineReceipt.configurationIdentity,
322	    requiredOwnership: set.requirements,
323	    authoredIds: set.requirements.filter((r) => r.owner !== null).map((r) => r.id),
324	    ...requiredObservations(
325	      set,
326	      observations.map((r) => r.result),
327	    ),
328	    reviewedWholeIds: set.coverage.rows.filter((r) => r.wholeContract).map((r) => r.id),
329	    omittedRequiredIds: set.requirements.filter((r) => r.owner === null).map((r) => r.id),
330	    optionalCatalogIds: first.result.selectedScenarioIds.filter(
331	      (id) => !set.requirements.some((r) => r.id === id),
332	    ),
333	    shards: summary,
334	  };
335	}
336	
337	/** Safe attempt evidence is separate from the all-checks-passed set summary. */
338	export function createArtifactEvidenceWriter(
339	  set: ReadUpdateArtifactSet,
340	  sourceCommit: string,
341	  filename: string | undefined,
342	  credentialValues: readonly string[],
343	) {
344	  assertReadUpdateArtifactSet(set);
345	  const credentials = [...credentialValues];
346	  if (!/^[a-f0-9]{40}$/.test(sourceCommit) || credentials.some((s) => !s))
347	    throw Error("invalid evidence writer identity");
348	  if (
349	    filename &&
350	    [
351	      filename,
352	      `${filename}.attempt.json`,
353	      ...set.shards.map((s) => `${filename}.${s.id}.json`),
354	    ].some(existsSync)
355	  )
356	    throw Error("evidence output already exists; choose a fresh attempt path");
357	  type Cleanup = "not-started" | "pending" | "complete" | "failed";
358	  const rows = set.shards.map((s) => ({
359	    id: s.id,
360	    source: s.source,
361	    manifestDigest: s.bundle.digests.manifestDigest,
362	    status: "unobserved" as "unobserved" | "running" | "returned" | "aborted" | "failed",
363	    cleanup: "not-started" as Cleanup,
364	    evidence: "absent" as "absent" | "retained" | "withheld-credential",
365	    resultDigest: undefined as string | undefined,
366	    writtenReportDigest: undefined as string | undefined,
367	    writtenReportBytes: undefined as number | undefined,
368	    timing: undefined as
369	      | {
370	          budgetRemainingMsAtStart: number;
371	          elapsedMs: number;
372	          outcome: "running" | "pass" | "aborted" | "failed";
373	        }
374	      | undefined,
375	  }));
376	  const snapshots = new Map<number, Record<string, unknown>>();
377	  let failed = false;
378	  type FailureStage = "execution" | "assertion" | "cleanup" | "credential-check";
379	  const failureStages: FailureStage[] = [];
380	  function safeJson(value: unknown) {
381	    const text = JSON.stringify(value, null, 2);
382	    function inspect(v: unknown): boolean {
383	      if (typeof v === "string") {
384	        const candidates = [v];
385	        if (v.length % 4 === 0 && /^[A-Za-z0-9+/]+={0,2}$/.test(v))
386	          candidates.push(Buffer.from(v, "base64").toString("utf8"));
387	        try {
388	          candidates.push(decodeURIComponent(v));
389	        } catch {
390	          /* Non-URI strings remain checked literally. */
391	        }
392	        return candidates.some((candidate) =>
393	          credentials.some((secret) => candidate.includes(secret)),
394	        );
395	      }
396	      return (
397	        v !== null &&
398	        typeof v === "object" &&
399	        Object.entries(v).some(([key, value]) => inspect(key) || inspect(value))
400	      );
401	    }
402	    if (inspect(JSON.parse(text))) throw Error("credential-bearing evidence withheld");
403	    return text;
404	  }
405	  // Cleanup metadata replaces a complete file atomically. A failed replacement
406	  // leaves previously returned genuine evidence intact (not a power-loss claim).
407	  function replaceFile(destination: string, encoded: string) {
408	    const temporary = `${destination}.pending-${randomUUID()}`;
409	    try {
410	      writeFileSync(temporary, encoded, { flag: "wx", mode: 0o600 });
411	      renameSync(temporary, destination);
412	    } catch (error) {
413	      try {
414	        rmSync(temporary, { force: true });
415	      } catch (cleanup) {
416	        throw new AggregateError([error, cleanup], "evidence replacement and cleanup failed", {
417	          cause: error,
418	        });
419	      }
420	      throw error;
421	    }
422	  }
423	  function ledger(outcome: "running" | "failed" | "observed", stage?: FailureStage) {
424	    if (stage && !failureStages.includes(stage)) failureStages.push(stage);
425	    const value = {
426	      claimEligible: false,
427	      outcome,
428	      ...(failureStages.length
429	        ? { failureStage: failureStages[0], failureStages: [...failureStages] }
430	        : {}),
431	      sourceCommit,
432	      ...set.digests,
433	      ...requiredObservations(
434	        set,
435	        set.shards.map(
436	          (_, index) => snapshots.get(index)?.result as ConformanceRunResult | undefined,
437	        ),
438	      ),
439	      shards: rows.map((r) => ({
440	        ...r,
441	        ...(r.evidence === "retained" && filename ? { report: `${filename}.${r.id}.json` } : {}),
442	      })),
443	    };
444	    const encoded = safeJson(value);
445	    if (filename) replaceFile(`${filename}.attempt.json`, encoded);
