469	      // Only known wrapper fields accompany the genuine runner result. Never retain
470	      // thrown errors, child stderr, resolver functions or arbitrary wrapper keys.
471	      const extra = report as ArtifactObservation & {
472	        observations?: unknown;
473	        setupObservations?: unknown;
474	        nativeReadObservations?: unknown;
475	        sourceDirty?: boolean;
476	      };
477	      const snapshot = {
478	        claimEligible: false,
479	        sourceCommit: report.sourceCommit,
480	        configuration: report.configuration,
481	        baselineReceipt: readySummary(report.baselineReceipt),
482	        sessions: report.sessions.map((s) => ({ scenario: s.scenario, ...readySummary(s) })),
483	        catalogSources: report.catalogSources,
484	        plannedManifestDigest: report.plannedManifestDigest,
485	        plannedIds: report.plannedIds,
486	        requiredIds: report.requiredIds,
487	        exactConfiguration: {
488	          scope: report.exactConfiguration.scope,
489	          profile: report.exactConfiguration.profile,
490	          routes: report.exactConfiguration.routes,
