492	          maximumRequestBodyBytes: report.exactConfiguration.maximumRequestBodyBytes,
493	          credentialHandles: report.exactConfiguration.credentialHandles,
494	          defaultCredentialRef: report.exactConfiguration.defaultCredentialRef,
495	        },
496	        result: report.result,
497	        observations: extra.observations,
498	        setupObservations: extra.setupObservations,
499	        nativeReadObservations: extra.nativeReadObservations,
500	        sourceDirty: extra.sourceDirty,
501	      };
502	      let captured: Record<string, unknown>;
503	      try {
504	        // Capture once: later caller mutation cannot corrupt a retained child report.
505	        captured = JSON.parse(safeJson(snapshot));
506	      } catch (error) {
