1	import { PROTOCOL_PROFILES, type ProtocolProfile } from "@bdp/protocol";
2	
3	import type { ScenarioCatalog, ScenarioMetadata } from "./catalog.js";
4	
5	/** Whether a claimed cumulative profile includes the required lower profile. */
6	export function profileIncludes(
7	  claimedProfile: ProtocolProfile,
8	  requiredProfile: ProtocolProfile,
9	): boolean {
10	  const claimedRank = profileRank(claimedProfile);
11	  const requiredRank = profileRank(requiredProfile);
12	  return claimedRank >= requiredRank;
13	}
14	
15	/**
16	 * The ids every applicable row of the claimed profile retires. A retired row
