1	/** Source-only two-artifact planning boundary. No execution, qualification or public admission. */
2	import { createHash } from "node:crypto";
3	import {
4	  copySourceBytes,
5	  createCumulativeReadUpdateArtifactBundle,
6	  CUMULATIVE_MANIFEST_MAX_BYTES,
7	  parseBoundedJson,
8	  type ConformanceArtifactBundle,
9	  type ConformanceArtifactSource,
10	} from "../src/artifact-bundle.js";
11	import { canonicalJson } from "../src/canonical-json.js";
12	import {
13	  assertCanonicalProfileContractSelection,
14	  type ProfileContractSelection,
15	} from "../src/profile-contract-selection.js";
16	import { ownData } from "./profile-contract-plan.js";
17	
18	const INDEX_MAX_BYTES = 16_384;
19	const ID = /^[a-z0-9]+(?:[.-][a-z0-9]+)*$/;
20	// Deliberately closed to ordinary flat matrix filenames; never an import resolver.
21	const SOURCE = /^matrices\/[a-z0-9]+(?:[.-][a-z0-9]+)*\.json$/;
22	
23	export interface ReadUpdateArtifactSetSources {
24	  readonly index: ConformanceArtifactSource;
25	  readonly fixture: ConformanceArtifactSource;
26	  readonly coverage: ConformanceArtifactSource;
27	  readonly manifests: Readonly<Record<string, ConformanceArtifactSource>>;
28	}
29	interface IndexEntry {
30	  readonly id: string;
31	  readonly source: string;
32	}
33	interface CoverageRow {
34	  readonly id: string;
35	  readonly status: "bounded-observation" | "omitted";
36	  /** Authored review decision only; this validator does not grant whole-contract credit. */
37	  readonly wholeContract: boolean;
38	  readonly reason: string;
39	  readonly bindings: readonly {
40	    readonly scenario: string;
41	    readonly assertions: readonly string[];
42	  }[];
43	}
44	export interface ReadUpdateArtifactSet {
45	  readonly claimEligible: false;
46	  readonly selection: ProfileContractSelection;
47	  readonly index: { readonly version: 1; readonly shards: readonly IndexEntry[] };
48	  readonly coverage: {
49	    readonly version: 1;
50	    readonly claimEligible: false;
51	    readonly rows: readonly CoverageRow[];
52	  };
53	  readonly shards: readonly {
54	    readonly id: string;
55	    readonly source: string;
56	    readonly bundle: ConformanceArtifactBundle;
57	    readonly scenarioIds: readonly string[];
58	    readonly sourceBytes: number;
59	  }[];
60	  readonly requirements: readonly { readonly id: string; readonly owner: string | null }[];
61	  readonly digests: {
62	    readonly setDigest: string;
63	    readonly indexDigest: string;
64	    readonly coverageDigest: string;
65	    readonly fixtureDigest: string;
66	    readonly catalogDigests: Readonly<Record<string, string>>;
67	  };
68	  /** Unique captured input bytes only, not repeated parses, retained reports or heap allocation. */
69	  readonly sourceBytes: {
70	    readonly index: number;
71	    readonly fixture: number;
72	    readonly coverage: number;
73	    readonly manifests: number;
74	  };
75	}
76	const sets = new WeakMap<ReadUpdateArtifactSet, ReadUpdateArtifactSetSources>();
77	
78	function source(
79	  input: unknown,
80	  kind: "manifest" | "fixture",
81	  role: string,
82	  limit?: number,
83	): ConformanceArtifactSource {
84	  try {
85	    const fields = ownData(input, ["bytes", "label"], ["bytes"]);
86	    if (fields.label !== undefined && typeof fields.label !== "string")
87	      throw Error("source label must be a string");
88	    // Role is fixed or derived from the validated index. Caller labels are not
89	    // attribution authority; intrinsic copying performs all byte/type/size checks.
90	    return {
91	      bytes: copySourceBytes({ bytes: fields.bytes as Uint8Array }, kind, limit),
92	      label: role,
93	    };
94	  } catch (cause) {
95	    throw Error(`${role}: ${cause instanceof Error ? cause.message : "invalid source"}`, { cause });
96	  }
97	}
98	function digest(bytes: string | Uint8Array): string {
99	  return createHash("sha256").update(bytes).digest("hex");
100	}
101	function freeze<T>(value: T): T {
102	  if (value && typeof value === "object" && !Object.isFrozen(value)) {
103	    for (const child of Object.values(value)) freeze(child);
104	    Object.freeze(value);
105	  }
106	  return value;
107	}
108	function parseIndex(bytes: Uint8Array): { version: 1; shards: IndexEntry[] } {
109	  const input = ownData(parseBoundedJson(bytes, "manifest", "artifact-set index"), [
110	    "version",
111	    "shards",
112	  ]);
113	  if (input.version !== 1 || !Array.isArray(input.shards) || input.shards.length !== 2)
114	    throw Error("artifact set requires version 1 and exactly two shards");
115	  const shards = input.shards.map((value) => {
116	    const entry = ownData(value, ["id", "source"]);
117	    if (
118	      typeof entry.id !== "string" ||
119	      entry.id.length > 128 ||
120	      !ID.test(entry.id) ||
121	      typeof entry.source !== "string" ||
122	      entry.source.length > 256 ||
123	      !SOURCE.test(entry.source)
124	    )
125	      throw Error("invalid artifact-set shard ID or matrix source name");
126	    return { id: entry.id, source: entry.source };
127	  });
128	  if (
129	    new Set(shards.map((s) => s.id)).size !== 2 ||
130	    new Set(shards.map((s) => s.source)).size !== 2
131	  )
132	    throw Error("duplicate artifact-set shard ID or source");
133	  return { version: 1, shards };
134	}
135	
136	export function createReadUpdateArtifactSet(
137	  selection: ProfileContractSelection,
138	  input: ReadUpdateArtifactSetSources,
139	): ReadUpdateArtifactSet {
140	  assertCanonicalProfileContractSelection(selection);
141	  if (selection.profile !== "read-update" || selection.history)
142	    throw Error("artifact set requires canonical baseline Read+Update selection");
143	  const fields = ownData(input, ["index", "fixture", "coverage", "manifests"]);
144	  const indexSource = source(fields.index, "manifest", "artifact-set index", INDEX_MAX_BYTES);
145	  const index = parseIndex(indexSource.bytes);
146	  const manifestFields = ownData(
147	    fields.manifests,
148	    index.shards.map((s) => s.source),
149	  );
150	  const fixture = source(fields.fixture, "fixture", "artifact-set fixture");
151	  const coverage = source(fields.coverage, "fixture", "artifact-set coverage");
152	  const manifests = Object.fromEntries(
153	    index.shards.map((s) => [
154	      s.source,
155	      source(
156	        manifestFields[s.source],
157	        "manifest",
158	        `${s.id} (${s.source})`,
159	        CUMULATIVE_MANIFEST_MAX_BYTES,
160	      ),
161	    ]),
162	  );
163	  // Every caller source has been captured. The factories only see detached bytes below.
164	  const positions = new Map(selection.required.map((row, n) => [row.id, n]));
165	  const owners = new Map<string, string>();
166	  const plans = new Map<string, ConformanceArtifactBundle["manifest"]["scenarios"][number]>();
167	  const shards = index.shards.map((entry) => {
168	    const captured = manifests[entry.source]!;
169	    const bundle = createCumulativeReadUpdateArtifactBundle(selection, {
170	      manifest: captured,
171	      fixture,
172	    });
173	    if (bundle.manifest.scenarios.length === 0) throw Error("artifact-set shard must not be empty");
174	    let previous = -1;
175	    for (const row of bundle.manifest.scenarios) {
176	      for (const gate of ["setup", "applicability"] as const) {
177	        if (
178	          row[gate].requires.some((capability) => !bundle.fixture.capabilities.includes(capability))
179	        )
180	          throw Error(
181	            `${entry.id} (${entry.source}): owned scenario ${row.id} has unavailable ${gate} capabilities`,
182	          );
183	      }
184	      const position = positions.get(row.id)!; // Ordinary cumulative factory validates membership.
185	      if (position <= previous) throw Error("shard scenarios must follow canonical required order");
186	      previous = position;
187	      if (owners.has(row.id)) throw Error(`duplicate scenario owner: ${row.id}`);
188	      owners.set(row.id, entry.id);
189	      plans.set(row.id, row);
190	    }
191	    return {
192	      ...entry,
193	      bundle,
194	      scenarioIds: bundle.manifest.scenarios.map((r) => r.id),
195	      sourceBytes: captured.bytes.byteLength,
196	    };
197	  });
