        (error: unknown) => ({ ok: false as const, error }),
      );
      stage.elapsedMs = performance.now() - started;
      stage.remainingMs = Math.max(0, 90000 - stage.elapsedMs);
      stage.outcome = controller.signal.aborted
        ? "aborted"
