1	/**
2	 * RFC 8785 JSON Canonicalization Scheme (JCS) serialization.
3	 *
4	 * One implementation serves every digest this package binds — the cohort
5	 * artifact's committed bytes and the Read schema projection — because two
6	 * serializers that could drift would be two definitions of "the same bytes".
7	 *
8	 * JCS is exactly what ECMAScript `JSON.stringify` produces for scalars: ES
9	 * number formatting, `\"` and `\\`, the short control escapes with lowercase
10	 * `\u00xx` for the remaining control characters, and non-ASCII emitted as is.
11	 * On top of that, object members are ordered by UTF-16 code units and no
12	 * insignificant whitespace is emitted. Non-finite numbers have no JSON
13	 * spelling and are refused rather than degraded to `null`; `undefined`
14	 * members are omitted exactly as `JSON.stringify` omits them.
15	 */
16	export class CanonicalJsonError extends Error {
17	  constructor(message: string, options: ErrorOptions = {}) {
18	    super(message, options);
19	    this.name = "CanonicalJsonError";
20	  }
21	}
22	
23	export function canonicalJson(value: unknown): string {
24	  if (value === null) return "null";
25	  if (typeof value === "boolean") return value ? "true" : "false";
26	  if (typeof value === "number") {
27	    if (!Number.isFinite(value)) {
28	      throw new CanonicalJsonError("canonical JSON numbers must be finite");
29	    }
30	    return JSON.stringify(value);
31	  }
32	  if (typeof value === "string") return JSON.stringify(value);
33	  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
34	  if (typeof value === "object") {
35	    const entries = Object.entries(value as Record<string, unknown>)
36	      .filter(([, entry]) => entry !== undefined)
37	      .sort(([left], [right]) => compareCodeUnits(left, right));
38	    return `{${entries.map(([key, entry]) => `${JSON.stringify(key)}:${canonicalJson(entry)}`).join(",")}}`;
39	  }
40	  throw new CanonicalJsonError(`canonical JSON cannot serialize ${typeof value}`);
41	}
42	
43	/** Order strings by UTF-16 code units, the member order RFC 8785 requires. */
44	export function compareCodeUnits(left: string, right: string): number {
45	  return left < right ? -1 : left > right ? 1 : 0;
46	}
